mapper.insert:
insert INTO ${database.prefix.order}hou_order_invoice_info( order_id, invoice_amount, invoice_status, user_id, user_name, user_mobile, user_mail, address_province, address_city, address_area, address_detail, invoice_type, invoice_head_type, invoice_head, company_tax_id, register_address, register_number, opening_bank, bank_account, invoice_content
) values( #{param.orderId}, #{param.invoiceAmount}, #{param.invoiceStatus}, #{param.userId}, #{param.userName}, #{param.userMobile}, #{param.userMail}, #{param.addressProvince}, #{param.addressCity}, #{param.addressArea}, #{param.addressDetail}, #{param.invoiceType}, #{param.invoiceHeadType}, #{param.invoiceHead}, #{param.companyTaxId}, #{param.registerAddress}, #{param.registerNumber}, #{param.openingBank}, #{param.bankAccount}, #{param.invoiceContent}
)

mapper.update:
update ${database.prefix.order}hou_order_base
set invoice_status = #{param.invoiceStatus},
    invoice_id = #{param.invoiceId}
where order_id = #{param.orderId}

mapper.select:
select a.order_id, a.create_time as invoiceCreateTime, a.finish_time as invoiceFinishTime, a.invoice_status, a.invoice_id, a.invoice_amount, a.invoice_content, a.invoice_type, a.invoice_head_type, a.invoice_head, b.shop_id, b.shop_name, b.buyer_user_name, b.order_status FROM ${database.prefix.order}hou_order_invoice_info a left join ${database.prefix.order}hou_order_base b on a.order_id = b.order_id
and a.invoice_type = #{param.invoiceType}
and a.invoice_status = #{param.invoiceStatus}
and b.buyer_user_name like concat("%",#{param.buyerUserName},"%")
and a.order_id = #{param.orderId}
and a.create_time >= #{param.invoiceCreateStartTime}
and a.create_time <= #{param.invoiceCreateEndTime}
and a.finish_time >= #{param.invoiceFinishStartTime}
and a.finish_time <= #{param.invoiceFinishEndTime}
order by a.create_time desc

select ooii.bank_account, ooii.opening_bank
FROM ${database.prefix.order}hou_order_invoice_info ooii
where order_id = #{orderId}
